/**
 * 一键套餐（组合餐）
 * 健身人群在外常吃的「点单组合」，一键批量加入食物清单。
 * 结构：
 * {
 *   name: 套餐名,
 *   tag: 分类标签（如「沙县小吃」「兰州拉面」「快餐」），
 *   note: 说明（可含「可去酱/少糖」提示）,
 *   items: [ { n: 食物名(引用 FOODS/BRAND_FOODS 的 name), g: 克数 或 servings: 份数 } ]
 * }
 * 份量按普通成年男性一顿的常见量设计，实际可手动增删。
 */
